ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'reports/testing'
OUT.mkdir(parents=True, exist_ok=True)
XLSX = OUT / 'final-test-workbook.xlsx'
if XLSX.exists():
    old = load_workbook(XLSX)
    for row in old['Test Cases'].iter_rows(min_row=6):
        if row[12].value not in (None, 'Not Started') or any(c.value for c in row[13:]):
            raise SystemExit('Recorded test results exist. Preserve this workbook; generate a new blank version deliberately.')
    if any(c.value for row in old['Issues & Retests'].iter_rows(min_row=6) for c in row):
        raise SystemExit('Issue/retest records exist. Preserve this workbook.')

cases = []
def add(stage, role, workspace, function, pre, asset, steps, expected, change='Read only', live='No', ref='3.1.2; 3.2.2-3.2.4'):
    cases.append([f'TC-{len(cases)+1:03}', stage, role, workspace, ref, function, pre, asset, steps, expected, change, live,
                  'Not Started', None, None, None, None, None, None, None, None])

