def banner(ws,title,subtitle,last):
    ws.merge_cells(start_row=1,start_column=1,end_row=1,end_column=last);ws.cell(1,1,title);ws.row_dimensions[1].height=30
    ws.cell(1,1).font=Font(name='Arial',size=16,bold=True,color='FFFFFF');ws.cell(1,1).fill=PatternFill('solid',fgColor=navy)
    ws.merge_cells(start_row=2,start_column=1,end_row=2,end_column=last);ws.cell(2,1,subtitle);ws.cell(2,1).alignment=Alignment(wrap_text=True,vertical='top');ws.row_dimensions[2].height=34
def headers(ws,row,values):
    for col,value in enumerate(values,1):
        c=ws.cell(row,col,value);c.fill=PatternFill('solid',fgColor=navy);c.font=Font(name='Arial',bold=True,color='FFFFFF');c.alignment=Alignment(wrap_text=True,vertical='center')
    ws.row_dimensions[row].height=30
def style_cells(ws,min_row,max_row,max_col):
    for row in ws.iter_rows(min_row=min_row,max_row=max_row,max_col=max_col):
        for c in row:
            c.font=Font(name='Arial',size=11);c.alignment=Alignment(vertical='top',wrap_text=True)
            if c.row%2==0:c.fill=PatternFill('solid',fgColor=light)

