W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
def esc(s):return html.escape(s,quote=True)
paras=[]
for line in (OUT/'reviewer-guide.md').read_text(encoding='utf-8').splitlines():
    if not line.strip():continue
    heading=re.match(r'^(#{1,3}) (.+)$',line)
    text=heading.group(2) if heading else line
    style=('Title' if len(heading.group(1))==1 else 'Heading'+str(len(heading.group(1))-1)) if heading else 'Normal'
    paras.append(f'<w:p><w:pPr><w:pStyle w:val="{style}"/><w:jc w:val="both"/><w:spacing w:after="120" w:line="480" w:lineRule="auto"/>'+('<w:keepNext/>' if heading else '')+f'</w:pPr><w:r><w:t xml:space="preserve">{esc(text)}</w:t></w:r></w:p>')
document=f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="{W}"><w:body>'+''.join(paras)+'<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>'
styles=f'<w:styles xmlns:w="{W}"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="24"/></w:rPr></w:rPrDefault></w:docDefaults>'
for style in ['Normal','Title','Heading1','Heading2']:
    styles+=f'<w:style w:type="paragraph" w:styleId="{style}"><w:name w:val="{style}"/><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="24"/>'+('<w:b/>' if style!='Normal' else '')+'</w:rPr></w:style>'
styles+='</w:styles>'
